def cents(dollars):
    return round(dollars * 100)


def format_cents(amount):
    return '$%d.%02d' % (amount // 100, amount % 100)
import unittest

from bill.money import cents, format_cents


class MoneyTest(unittest.TestCase):
    def test_cents_and_format(self):
        self.assertEqual(cents(5), 500)
        self.assertEqual(format_cents(1299), '$12.99')


if __name__ == '__main__':
    unittest.main()
